package cc.nekocat.waylamaps.data

import cc.nekocat.waylamaps.data.db.SpeedCameraEntity
import kotlinx.serialization.SerialName
import kotlinx.serialization.Serializable
import kotlinx.serialization.json.Json

/** Bundled speed camera dataset, generated by `tools/convert_speed_cameras.py`. */
@Serializable
data class SpeedCameraAsset(
    val version: String,
    val source: String,
    val license: String,
    /** SHA-256 of the raw CSV the asset was generated from. */
    @SerialName("source_sha256") val sourceSha256: String? = null,
    val cameras: List<Camera>,
) {
    @Serializable
    data class Camera(
        val lat: Double,
        val lng: Double,
        val city: String,
        val district: String,
        val address: String,
        val direction: String,
        /** Enforced travel direction in degrees (0 = north); null means both ways or unknown. */
        val bearing: Int? = null,
        val limit: Int? = null,
    )

    companion object {
        const val FILE_NAME = "speed_cameras.json"

        private val json = Json { ignoreUnknownKeys = true }

        fun parse(text: String): SpeedCameraAsset = json.decodeFromString(text)
    }
}

fun SpeedCameraAsset.Camera.toEntity() = SpeedCameraEntity(
    lat = lat,
    lng = lng,
    city = city,
    district = district,
    address = address,
    directionText = direction,
    bearingDeg = bearing,
    limitKmh = limit,
)
